package com.mahesh.empleave.audit;import com.mahesh.empleave.common.dto.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/audit-logs") @RequiredArgsConstructor public class AuditLogController{private final AuditLogRepository repo;@GetMapping @PreAuthorize("hasRole('ADMIN')") Page<ApiDtos.Audit> all(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return repo.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())).map(ApiDtos::audit);}}
